<body><a class="skip" href="#main"><?=$en?'Skip to content':'Đến nội dung'?></a><header class="site-header"><div class="site-header-inner"><a class="brand" href="<?=$homePath?>"><?php if($logo):?><img src="<?=$e($logo)?>" alt=""><?php endif;?><?=$e($branding['name'])?><span aria-hidden="true">✳</span></a><nav aria-label="<?=$en?'Main navigation':'Điều hướng chính'?>"><a href="<?=$en?'/en/blog':'/cam-nang'?>"><?=$en?'Journal':'Cẩm nang'?></a><?php foreach($navigation as $item)if($item['menu']):?><a href="<?=$e($item['href'])?>"<?=$item['href']===$canonicalPath?' aria-current="page"':''?>><?=$e($item['label'])?></a><?php endif;?></nav><div class="language"><?php foreach($languagePaths as $locale=>$url):?><a href="<?=$e($url)?>" lang="<?=$locale?>"<?=$lang===$locale?' aria-current="true"':''?>><?=$locale==='vi'?'VI':'EN'?></a><?php endforeach;?></div></div></header>
<main id="main" class="section">
<?php if($home):?>
<section class="home-hero"><p class="eyebrow"><?=$en?'THE LOCAL EXPERIENCE':'ĐI ĐỂ CÓ CHUYỆN KỂ'?></p><h1><?=$en?'Small journeys.':'Chuyến đi nhỏ.'?><br><em><?=$en?'Lasting memories.':'Kỷ niệm lớn.'?></em></h1><p class="lead"><?=$en?'Stories, information and local inspiration for your next journey.':'Thông tin, câu chuyện và cảm hứng địa phương cho hành trình tiếp theo của bạn.'?></p></section>
<?php if($publicProducts):?><section class="page-index"><p class="eyebrow"><?=$en?'LOCAL EXPERIENCES':'TRẢI NGHIỆM ĐỊA PHƯƠNG'?></p><h2><?=$en?'Where will you go next?':'Bạn muốn đi đâu hôm nay?'?></h2><div class="page-grid"><?php foreach($publicProducts as $item):?><a class="page-card" href="<?=$e(($en?'/en':'').'/ve/'.$item['slug'])?>"><?php if($media($item['cover'])):?><img class="product-thumb" src="<?=$e($media($item['cover']))?>" alt="<?=$e($item['cover']['alt'] ?: $item['name'])?>" loading="lazy"><?php endif;?><p class="eyebrow"><?=$e($item['destination'])?></p><h3><?=$e($item['name'])?></h3><p><?=$e(mb_substr($item['description'],0,180))?></p><span><?=$en?'View experience':'Xem trải nghiệm'?> ↗</span></a><?php endforeach;?></div></section><?php endif;?>
<section class="page-index"><div class="section-heading"><p class="eyebrow"><?=$en?'GOOD TO KNOW':'THÔNG TIN HỮU ÍCH'?></p><h2><?=$en?'Before your next journey':'Trước chuyến đi tiếp theo'?></h2></div><div class="page-grid"><?php foreach($published as $item):?><a class="page-card" href="<?=$e($item['localePaths'][$lang])?>"><h3><?=$e($item['title'])?></h3><p><?=$e($item['description'])?></p><span><?=$en?'Read more':'Xem thêm'?> ↗</span></a><?php endforeach;?><?php if(!$published):?><p class="muted"><?=$en?'More information is coming soon.':'Thông tin đang được cập nhật.'?></p><?php endif;?></div></section>
