<nav class="breadcrumbs" aria-label="<?=$en?'Breadcrumbs':'Đường dẫn'?>"><a href="<?=$homePath?>"><?=$en?'Home':'Trang chủ'?></a><span>/</span><span><?=$e($page['title'])?></span></nav>
<header class="content-page-heading"><p class="eyebrow"><?=$contact?($en?'LET’S PLAN YOUR NEXT EXPERIENCE':'CÙNG CHUẨN BỊ CHO CHUYẾN ĐI'):$e($branding['name']).' · '.($en?'INFORMATION':'THÔNG TIN')?></p><h1><?=$e($page['title'])?></h1><?php if($page['description']):?><p><?=$e($page['description'])?></p><?php endif;?></header>
