<div class="content-page-layout<?=$contact?' has-contact':''?>"><div class="content-page-body"><article class="prose"><?=ContentHtml::clean($page['contentHtml'])?></article>
<?php if($contact):?>
<section class="contact-form-panel"><p class="eyebrow"><?=$en?'WE’RE HERE TO HELP':'LUÔN SẴN SÀNG HỖ TRỢ'?></p><h2><?=$en?'Send us a message':'Gửi lời nhắn cho chúng mình'?></h2><p class="muted"><?=$en?'Tell us how we can help with your next experience.':'Để lại thông tin và nội dung cần hỗ trợ. Chúng mình sẽ liên hệ lại với bạn.'?></p>
<form id="contact-form" data-locale="<?=$lang?>"><fieldset><div class="contact-form-grid"><?php foreach([['name',$en?'Your name':'Họ tên','text',100,2],['email','Email','email',200,1],['phone',$en?'Phone (optional)':'Điện thoại (không bắt buộc)','tel',30,0],['subject',$en?'Subject':'Chủ đề','text',180,3]] as [$key,$label,$type,$max,$min]):?><label><?=$label?><input name="<?=$key?>" type="<?=$type?>" maxlength="<?=$max?>"<?=$min?' required minlength="'.$min.'"':''?> autocomplete="<?=$key==='name'?'name':($key==='email'?'email':($key==='phone'?'tel':'off'))?>"></label><?php endforeach;?></div><label><?=$en?'Message':'Nội dung'?><textarea name="message" rows="5" required minlength="10" maxlength="5000"></textarea></label><label class="contact-form-trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off" maxlength="200"></label><p class="contact-form-privacy"><?=$en?'Your details are used to respond to this request. This form does not confirm a booking.':'Thông tin được dùng để phản hồi yêu cầu này. Biểu mẫu không xác nhận đặt vé.'?></p><button class="button" type="submit"><?=$en?'Send message':'Gửi yêu cầu'?> ↗</button></fieldset><p id="contact-error" class="error" role="alert" hidden></p></form><div id="contact-success" class="contact-form-success" role="status" hidden><h3><?=$en?'Message received':'Đã nhận lời nhắn'?></h3><p><?=$en?'Thank you. Our team will review your request and get back to you.':'Cảm ơn bạn. Đội ngũ sẽ xem yêu cầu và liên hệ lại với bạn.'?></p><button type="button" class="outline-button" id="another-message"><?=$en?'Send another message':'Gửi lời nhắn khác'?></button></div><noscript><p><?=$en?'Enable JavaScript to send this form.':'Bật JavaScript để gửi biểu mẫu liên hệ.'?></p></noscript></section>
<?php endif;?></div>
<?php if($contact):?><aside class="contact-sidebar"><div class="contact-cards">
<?php foreach([['phone',$en?'Call us':'Điện thoại'],['email','Email'],['address',$en?'Visit us':'Địa chỉ'],['hours',$en?'Support hours':'Giờ hỗ trợ']] as [$key,$label])if($contact[$key]):?><div class="contact-card"><small><?=$label?></small><strong><?php if($key==='phone'):?><a href="tel:<?=$e(preg_replace('/[^+0-9]/','',$contact[$key]))?>"><?=$e($contact[$key])?></a><?php elseif($key==='email'):?><a href="mailto:<?=$e($contact[$key])?>"><?=$e($contact[$key])?></a><?php else:?><?=$e($contact[$key])?><?php endif;?></strong><?php if($key==='address' && $contact['mapUrl'] && str_starts_with($contact['mapUrl'],'https://')):?><a href="<?=$e($contact['mapUrl'])?>" target="_blank" rel="noopener noreferrer"><?=$en?'View map':'Xem bản đồ'?> ↗</a><?php endif;?></div><?php endif;?></div></aside><?php endif;?></div>
<?php endif;?></main>
<footer class="site-footer"><div><strong><?=$e($branding['name'])?></strong><p><?=$e($branding['companyName'])?></p><?php if($branding['address']):?><p><?=$e($branding['address'])?></p><?php endif;?></div><nav aria-label="<?=$en?'Footer':'Chân trang'?>"><a href="<?=$en?'/en/orders':'/tra-cuu'?>"><?=$en?'Find booking':'Tra cứu đơn'?></a><?php foreach($navigation as $item)if($item['footer']):?><a href="<?=$e($item['href'])?>"><?=$e($item['label'])?></a><?php endif;?></nav><small>© <?=gmdate('Y')?> <?=$e($branding['name'])?></small></footer>
